begin
  select id into demo from auth.users where lower(email) = lower(CORREO_DEMO);
  if demo is null then
    raise exception 'No existe ninguna cuenta con el correo %. Créala primero en Authentication → Users.', CORREO_DEMO;
  end if;

  -- 1 · Que sea miembro, o la app le dirá que le falta el código
  insert into public.miembros (user_id, codigo) values (demo, 'DEMO')
    on conflict (user_id) do nothing;

  -- 2 · Los datos
  insert into public.perfiles_estado (user_id, json) values (demo, estado)
    on conflict (user_id) do update set json = excluded.json, actualizado = now();

  -- 3 · El candado. RESTRICTIVE se combina con Y (no con O) sobre las
  --     políticas permisivas que ya hay, así que esto RESTA permiso a
  --     esta cuenta sin tocar el de nadie más. El id va escrito como
  --     literal dentro de la política, no leído de auth.users: una
  --     política no puede consultar esa tabla con el rol authenticated.
  drop policy if exists "la demo no escribe (update)" on public.perfiles_estado;
  execute format($f$
    create policy "la demo no escribe (update)" on public.perfiles_estado
      as restrictive for update to authenticated
      using      ( (select auth.uid()) is distinct from %L::uuid )
      with check ( (select auth.uid()) is distinct from %L::uuid )$f$, demo, demo);

  drop policy if exists "la demo no escribe (insert)" on public.perfiles_estado;
  execute format($f$
    create policy "la demo no escribe (insert)" on public.perfiles_estado
      as restrictive for insert to authenticated
      with check ( (select auth.uid()) is distinct from %L::uuid )$f$, demo);

  raise notice 'Cuenta de demostración lista: %  (id %)', CORREO_DEMO, demo;
end $$;


-- ── Comprobación ───────────────────────────────────────────────
-- `apuntes` debe dar 214 y `meses` 12. Las dos políticas tienen que
-- aparecer con permissive = RESTRICTIVE.

select
  jsonb_array_length(json->'apuntes')      as apuntes,
  jsonb_array_length(json->'aportaciones') as aportaciones,
  jsonb_array_length(json->'activos')      as activos,
  (select count(distinct a->>'mes') from jsonb_array_elements(json->'apuntes') a) as meses
from public.perfiles_estado
where user_id = (select id from auth.users where lower(email) = lower('demo@ahorrainvierte.es'));

select policyname, permissive, cmd
from pg_policies
where tablename = 'perfiles_estado'
order by permissive desc, policyname;


